  async function saveExpensePlan(e){e.preventDefault();if(!state.household)return;const amount=Number($('expensePlanAmount').value);if(!(amount>0)){toast('Enter an expected bill amount greater than zero.');return;}const file=$('expensePlanAttachment').files?.[0];if(file&&file.size>10*1024*1024){toast('Attachment must be 10 MB or smaller.');return;}const id=$('expensePlanForm').dataset.editId||null,old=id?state.expensePlans.find(p=>p.id===id):null;let path=old?.attachment_path||null;try{if(file){const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');path=`${state.household.id}/${crypto.randomUUID()}-${safe}`;const {error}=await state.client.storage.from('expense-attachments').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(error)throw error;}const payload={household_id:state.household.id,payee:$('expensePlanPayee').value.trim(),category:$('expensePlanCategory').value,description:$('expensePlanDescription').value.trim(),expected_amount:amount,paid_amount:Number(old?.paid_amount||0),due_date:$('expensePlanDue').value,owner:$('expensePlanOwner').value,frequency:$('expensePlanFrequency').value,notes:$('expensePlanNotes').value.trim()||null,attachment_path:path,created_by:state.user.id};const res=id?await state.client.from('expense_plans').update(payload).eq('id',id):await state.client.from('expense_plans').insert(payload);if(res.error)throw res.error;$('expensePlanForm').reset();delete $('expensePlanForm').dataset.editId;$('expensePlanForm').querySelector('button[type="submit"]').textContent='＋ Save expected bill';await refresh();toast(id?'Expected bill updated.':'Expected bill saved.');}catch(err){toast('Could not save expected bill: '+errText(err));}}
