  function accountTotals(){const totals=Object.fromEntries(accounts.map(a=>[a,Number(state.openingBalances.find(x=>x.account_name===a)?.opening_balance||0)]));for(const t of state.transactions){if(!validTx(t))continue;const amount=Number(t.amount||0),from=t.account_name||"Cash";if(!(from in totals))totals[from]=0;if(t.type==="income")totals[from]+=amount;else if(t.type==="expense")totals[from]+=(t.expense_is_refund?amount:-amount);else if(t.type==="transfer"){totals[from]-=amount;const to=t.to_account||"Other";if(!(to in totals))totals[to]=0;totals[to]+=amount;}}return totals;}
  function netWorth(){return Object.values(accountTotals()).reduce((s,v)=>s+Number(v||0),0)+state.assets.reduce((s,a)=>s+Number(a.estimated_value||0),0)+state.debts.filter(d=>d.debt_type==="receivable").reduce((s,d)=>s+Number(d.outstanding_amount||0),0)-state.debts.filter(d=>d.debt_type==="owed").reduce((s,d)=>s+Number(d.outstanding_amount||0),0);}
