    const trendMonths=Array.from({length:6},(_,i)=>{const d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()-(5-i));const m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const budget=state.budgets.filter(b=>String(b.month_start).slice(0,7)===m).reduce((n,b)=>n+Number(b.limit_amount||0),0);const actual=state.transactions.filter(t=>!t.is_reversed&&!t.is_reversal&&t.type==='expense'&&!t.is_debt_principal&&String(t.transaction_date).slice(0,7)===m).reduce((n,t)=>n+(t.expense_is_refund?-1:1)*Number(t.amount||0),0);return {m,budget,actual};});const prevActual=trendMonths.length>1?trendMonths[trendMonths.length-2].actual:0,currentActual=trendMonths[trendMonths.length-1]?.actual||0;const growthAlert=prevActual>0&&currentActual>prevActual*1.2?`<div class="income-alert">Spending is up ${Math.round((currentActual/prevActual-1)*100)}% compared with last month. Review categories before month-end.</div>`:'';const maxTrend=Math.max(1,...trendMonths.flatMap(x=>[x.budget,x.actual]));$('budgetTrend').innerHTML=growthAlert+`<div class="panel-head"><div><h3>SIX-MONTH BUDGET TREND</h3><p class="muted">Planned category limits compared with actual paid expenses.</p></div></div><div class="budget-trend-grid">${trendMonths.map(x=>`<div class="budget-trend-item"><div class="budget-trend-bars"><span title="Budget ${money(x.budget)}" style="height:${Math.max(3,x.budget/maxTrend*100)}%"></span><i title="Spent ${money(x.actual)}" style="height:${Math.max(3,x.actual/maxTrend*100)}%"></i></div><small>${x.m.slice(5)}</small><b>${money(x.actual)}</b></div>`).join('')}</div><p class="tiny muted">Blue = budget limits; red = actual expenses. Prior months with no budget show zero planned.</p>`;
