  async function saveBudgetSettings(e){e.preventDefault();if(!state.household)return;const month=$('budgetViewMonth').value||monthNow();try{const payload={household_id:state.household.id,created_by:state.user.id,month_start:month+'-01',planned_income:Number($('budgetPlannedIncomeInput').value||0),zero_based:$('budgetZeroBased').checked};const {error}=await state.client.from('household_budget_settings').upsert(payload,{onConflict:'household_id,month_start'});if(error)throw error;toast('Budget plan settings saved.');await refresh();}catch(e){toast('Could not save plan settings: '+errText(e));}}
  async function copyPreviousBudget(){if(!state.household)return;const target=$('budgetViewMonth').value||monthNow(),d=new Date(target+'-01T12:00:00');d.setMonth(d.getMonth()-1);const prev=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,old=state.budgets.filter(b=>String(b.month_start).slice(0,7)===prev);if(!old.length){toast('No budgets found for the previous month.');return;}if(!confirm(`Copy ${old.length} category budgets from ${prev} into ${target}? Existing matching category budgets will be updated.`))return;try{for(const b of old){let limit=Number(b.limit_amount||0);if(b.rollover_unused){const spent=budgetSpent(b);limit=Math.max(0,limit-spent)+limit;}const payload={household_id:state.household.id,created_by:state.user.id,category:b.category,month_start:target+'-01',limit_amount:Math.max(0.01,limit),owner_scope:b.owner_scope||'household',spending_kind:b.spending_kind||'need',rollover_unused:!!b.rollover_unused,notes:b.notes||null};const {error}=await state.client.from('household_budgets').upsert(payload,{onConflict:'household_id,category,month_start,owner_scope'});if(error)throw error;}const prior=currentBudgetSetting(prev);if(prior){const {error}=await state.client.from('household_budget_settings').upsert({household_id:state.household.id,created_by:state.user.id,month_start:target+'-01',planned_income:Number(prior.planned_income||0),zero_based:!!prior.zero_based},{onConflict:'household_id,month_start'});if(error)throw error;}await refresh();toast('Previous month copied. Review amounts before relying on the plan.');}catch(e){toast('Could not copy budgets: '+errText(e));}}
  async function applyBudgetForward(monthCount){if(!state.household)return;const sourceMonth=$('budgetViewMonth').value||monthNow(),source=state.budgets.filter(b=>String(b.month_start).slice(0,7)===sourceMonth);if(!source.length){toast('Create category budgets for the selected month first.');return;}const start=new Date(sourceMonth+'-01T12:00:00'),targets=[];for(let i=1;i<=monthCount;i++){const d=new Date(start);d.setMonth(d.getMonth()+i);targets.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);}if(!confirm(`Copy ${source.length} budget categories into ${targets.length} future month(s)? Existing matching budgets will be updated.`))return;try{for(const target of targets){for(const b of source){const payload={household_id:state.household.id,created_by:state.user.id,category:b.category,month_start:target+'-01',limit_amount:Number(b.limit_amount||0),owner_scope:b.owner_scope||'household',spending_kind:b.spending_kind||'need',rollover_unused:!!b.rollover_unused,notes:b.notes||null};const {error}=await state.client.from('household_budgets').upsert(payload,{onConflict:'household_id,category,month_start,owner_scope'});if(error)throw error;}const setting=currentBudgetSetting(sourceMonth);if(setting){const {error}=await state.client.from('household_budget_settings').upsert({household_id:state.household.id,created_by:state.user.id,month_start:target+'-01',planned_income:Number(setting.planned_income||0),zero_based:!!setting.zero_based},{onConflict:'household_id,month_start'});if(error)throw error;}}await refresh();toast('Budget templates copied. Review each month and adjust expected income.');}catch(e){toast('Could not apply budget template: '+errText(e));}}
  function exportBudgetCsv(){const month=$('budgetViewMonth').value||monthNow(),rows=state.budgets.filter(b=>String(b.month_start).slice(0,7)===month);const lines=[['Month','Category','Owner','Type','Limit','Spent','Remaining','Rollover','Notes'],...rows.map(b=>[month,b.category,b.owner_scope||'household',b.spending_kind||'need',Number(b.limit_amount||0),budgetSpent(b),Number(b.limit_amount||0)-budgetSpent(b),!!b.rollover_unused,b.notes||''])];downloadBlob(`nkausu-budget-${month}.csv`,new Blob([lines.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));}
