  function renderGoals(){$("goalList").innerHTML=state.goals.length?`<div class="goal-grid">${state.goals.map(g=>{const pct=Number(g.target_amount)?Number(g.current_amount)/Number(g.target_amount)*100:0;return `<article class="goal-card"><div class="panel-head"><h3>${escapeHtml(g.title)}</h3><button class="delete-btn" data-delete-row="savings_goals" data-id="${escapeHtml(g.id)}">Delete</button></div><strong>${money(g.current_amount)} <span>of ${money(g.target_amount)}</span></strong><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,pct)}%"></div></div><div class="transaction-meta">${Math.round(pct)}% saved${g.target_date?" · Target "+escapeHtml(g.target_date):""}</div><form class="inline-update" data-goal-update="${escapeHtml(g.id)}"><input type="number" min="0" step="0.01" value="${Number(g.current_amount)}" aria-label="Current saved amount"><button class="btn outline" type="submit">Update saved</button></form></article>`;}).join("")}</div>`:'<div class="empty">Add your first savings goal. Emergency fund is a useful option.</div>';}
  function renderDebts(){$("debtList").innerHTML=state.debts.length?`<div class="table-wrap"><table><thead><tr><th>RECORD</th><th>TYPE</th><th>ORIGINAL</th><th>OUTSTANDING</th><th>DUE</th><th>MONTHLY PAYMENT</th><th></th></tr></thead><tbody>${state.debts.map(d=>`<tr><td>${escapeHtml(d.name)}</td><td>${d.debt_type==="owed"?"We owe":"Owed to us"}</td><td>${money(d.original_amount)}</td><td>${money(d.outstanding_amount)}</td><td>${escapeHtml(d.due_date||"—")}</td><td>${money(d.monthly_payment||0)}</td><td><button class="delete-btn" data-edit-row="household_debts" data-id="${escapeHtml(d.id)}">Update</button> <button class="delete-btn" data-delete-row="household_debts" data-id="${escapeHtml(d.id)}">Delete</button></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No debts or receivables recorded.</div>';}
  function renderAssets(){
 const q=($("assetSearch")?.value||"").toLowerCase(),cat=$("assetCategoryFilter")?.value||"";
 const filtered=state.assets.filter(a=>(!cat||a.category===cat)&&(!q||[a.name,a.category,a.owner,a.location,a.notes].some(v=>String(v||"").toLowerCase().includes(q))));
 const total=state.assets.reduce((n,a)=>n+Number(a.estimated_value||0),0),cost=state.assets.reduce((n,a)=>n+Number(a.purchase_cost||0),0),debt=state.assets.reduce((n,a)=>n+Number(a.linked_debt||0),0);
 if($("assetTotalValue"))$("assetTotalValue").textContent=money(total);if($("assetTotalCost"))$("assetTotalCost").textContent=money(cost);if($("assetTotalEquity"))$("assetTotalEquity").textContent=money(total-debt);if($("assetCount"))$("assetCount").textContent=String(state.assets.length);
 const ownerTotals={me:0,wife:0,joint:0};const categoryTotals={};state.assets.forEach(a=>{const value=Number(a.estimated_value||0),owner=a.owner||"joint",share=Math.max(0,Math.min(100,Number(a.owner_share??100)))/100;ownerTotals[owner]=(ownerTotals[owner]||0)+value*share;categoryTotals[a.category]=(categoryTotals[a.category]||0)+value;});if($("assetBreakdown")){$("assetBreakdown").innerHTML=`<div class="asset-breakdown-grid"><div><h3>BY OWNER SHARE</h3>${Object.entries(ownerTotals).map(([k,v])=>`<div class="asset-breakdown-row"><span>${k==="me"?"Me":k==="wife"?"Wife":"Joint"}</span><strong>${money(v)}</strong></div>`).join("")}</div><div><h3>BY CATEGORY</h3>${Object.entries(categoryTotals).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="asset-breakdown-row"><span>${escapeHtml(k)}</span><strong>${money(v)}</strong></div>`).join("")||"No assets recorded yet."}</div></div>`;}
 const assetSales=state.transactions.filter(t=>t.category==="Asset sale"||t.category==="Asset sale proceeds");const currentAcquisitions=state.assets.filter(a=>a.acquired_on).map(a=>({date:a.acquired_on,name:a.name,type:"Asset registered / acquisition date",amount:Number(a.purchase_cost||0),owner:a.owner||"joint"}));const saleEvents=assetSales.map(t=>({date:t.transaction_date,name:t.description,type:"Sale proceeds recorded",amount:Number(t.amount||0),owner:t.paid_by||"joint"}));const events=[...currentAcquisitions,...saleEvents].sort((a,b)=>String(b.date).localeCompare(String(a.date)));if($("assetEventHistory"))$("assetEventHistory").innerHTML=events.length?`<div class="table-wrap"><table><thead><tr><th>DATE</th><th>ASSET / RECORD</th><th>EVENT</th><th>OWNER</th><th>AMOUNT</th></tr></thead><tbody>${events.map(v=>`<tr><td>${escapeHtml(v.date||"—")}</td><td>${escapeHtml(v.name)}</td><td>${escapeHtml(v.type)}</td><td>${escapeHtml(v.owner)}</td><td>${money(v.amount)}</td></tr>`).join("")}</tbody></table></div>`:"<div class='empty'>Asset acquisition and sale history will appear here.</div>";
 $("assetList").innerHTML=filtered.length?`<div class="table-wrap"><table><thead><tr><th>ASSET</th><th>CATEGORY / OWNER</th><th>PURCHASE COST</th><th>CURRENT VALUE</th><th>CHANGE</th><th>EQUITY</th><th>LOCATION / DATES</th><th>ACTIONS</th></tr></thead><tbody>${filtered.map(a=>{const change=Number(a.estimated_value||0)-Number(a.purchase_cost||0);return `<tr><td><strong>${escapeHtml(a.name)}</strong>${a.document_url?`${/\.(png|jpe?g|gif|webp)(\?.*)?$/i.test(a.document_url)?`<div class="asset-photo-preview"><a href="${escapeHtml(a.document_url)}" target="_blank" rel="noopener"><img src="${escapeHtml(a.document_url)}" alt="${escapeHtml(a.name)} photo" loading="lazy" onerror="this.parentElement.parentElement.style.display='none'"></a></div>`:""}<div class="asset-document-link"><a href="${escapeHtml(a.document_url)}" target="_blank" rel="noopener">Open document / photo</a></div>`:""}${a.notes?`<div class="transaction-meta">${escapeHtml(a.notes)}</div>`:""}</td><td>${escapeHtml(a.category)}<div class="transaction-meta">${escapeHtml(a.owner||"joint")} · ${Number(a.owner_share??100)}%</div></td><td>${money(a.purchase_cost||0)}</td><td>${money(a.estimated_value)}</td><td class="amount ${change>=0?"income":"expense"}">${change>=0?"+":"−"}${money(Math.abs(change))}</td><td>${money(Number(a.estimated_value||0)-Number(a.linked_debt||0))}<div class="transaction-meta">Debt: ${money(a.linked_debt||0)}</div></td><td>${escapeHtml(a.location||"—")}<div class="transaction-meta">Acquired: ${escapeHtml(a.acquired_on||"—")} · Valued: ${escapeHtml(a.valuation_date||"—")}</div>${a.insurance_expiry?`<div class="transaction-meta">Expiry: ${escapeHtml(a.insurance_expiry)}</div>`:""}</td><td><div class="row-actions"><button class="delete-btn" data-asset-edit="${escapeHtml(a.id)}">Edit</button><button class="delete-btn" data-asset-cost="${escapeHtml(a.id)}">Add cost</button>${Number(a.monthly_rental_income||0)>0?`<button class="delete-btn" data-asset-rent="${escapeHtml(a.id)}">Record rent</button>`:""}<button class="delete-btn" data-asset-sell="${escapeHtml(a.id)}">Record sale</button><button class="delete-btn" data-delete-row="household_assets" data-id="${escapeHtml(a.id)}">Delete</button></div></td></tr>`}).join("")}</tbody></table></div>`:'<div class="empty">No matching assets recorded.</div>';
 const expiring=state.assets.filter(a=>a.insurance_expiry&&((new Date(a.insurance_expiry)-new Date(today()))/86400000)<=60).sort((a,b)=>String(a.insurance_expiry).localeCompare(String(b.insurance_expiry)));
 $("assetReminderList").innerHTML=expiring.length?`<div class="table-wrap"><table><thead><tr><th>ASSET</th><th>INSURANCE / WARRANTY EXPIRY</th><th>PROVIDER</th><th>STATUS</th></tr></thead><tbody>${expiring.map(a=>{const days=Math.ceil((new Date(a.insurance_expiry)-new Date(today()))/86400000);return `<tr><td>${escapeHtml(a.name)}</td><td>${escapeHtml(a.insurance_expiry)}</td><td>${escapeHtml(a.insurance_provider||"—")}</td><td>${days<0?`Overdue by ${Math.abs(days)} days`:days===0?"Expires today":days<=14?`Due soon (${days} days)`:`Within 60 days (${days} days)`}</td></tr>`}).join("")}</tbody></table></div>`:'<div class="empty">No insurance or warranty expiry dates within the next 60 days.</div>';
 if($("assetValuationList")){const byId=new Map(state.assets.map(a=>[String(a.id),a]));const history=state.assetValuations||[];$("assetValuationList").innerHTML=history.length?`<div class="table-wrap"><table><thead><tr><th>ASSET</th><th>VALUATION DATE</th><th>RECORDED VALUE</th><th>CHANGE FROM PURCHASE COST</th><th>NOTES</th></tr></thead><tbody>${history.map(v=>{const a=byId.get(String(v.asset_id));const change=Number(v.value||0)-Number(a?.purchase_cost||0);return `<tr><td>${escapeHtml(a?.name||"Deleted asset")}</td><td>${escapeHtml(v.valuation_date||"—")}</td><td>${money(v.value)}</td><td class="amount ${change>=0?"income":"expense"}">${change>=0?"+":"−"}${money(Math.abs(change))}</td><td>${escapeHtml(v.notes||"—")}</td></tr>`}).join("")}</tbody></table></div>`:"<div class='empty'>No valuation history yet. Save an asset valuation to start its history.</div>";}
 }
 function resetAssetForm(){const f=$("assetForm");if(!f)return;f.reset();$("assetId").value="";$("assetShare").value="100";$("assetCost").value="0";$("assetDebt").value="0";$("assetRental").value="0";$("assetSaveButton").textContent="Add asset";}
 function editAsset(id){const a=state.assets.find(x=>String(x.id)===String(id));if(!a)return;const fields={assetId:a.id,assetName:a.name,assetCategory:a.category,assetCost:a.purchase_cost??0,assetValue:a.estimated_value??0,assetValuationDate:a.valuation_date||today(),assetDate:a.acquired_on||"",assetOwner:a.owner||"joint",assetShare:a.owner_share??100,assetLocation:a.location||"",assetDebt:a.linked_debt??0,assetInsurance:a.insurance_provider||"",assetExpiry:a.insurance_expiry||"",assetDocument:a.document_url||"",assetRental:a.monthly_rental_income??0,assetDepreciation:a.depreciation_notes||"",assetNotes:a.notes||""};Object.entries(fields).forEach(([k,v])=>{if($(k))$(k).value=v});$("assetSaveButton").textContent="Save changes";$("assetForm").scrollIntoView({behavior:"smooth",block:"start"});}
 async function addAssetCost(id){const a=state.assets.find(x=>String(x.id)===String(id));if(!a)return;const amount=prompt(`Enter maintenance/insurance cost for ${a.name} (ZMW):`);if(amount===null)return;if(!Number.isFinite(Number(amount))||Number(amount)<=0){toast("Enter a valid positive amount.");return;}const date=prompt("Cost date (YYYY-MM-DD):",today())||today();const note=prompt("Cost description:","Maintenance / insurance")||"Asset maintenance";openDialog("expense");$("recordAmount").value=Number(amount);$("recordDate").value=date;$("recordDescription").value=`${a.name} — ${note}`;$("recordCategory").value="Asset maintenance";if($("recordNotes"))$("recordNotes").value=`Asset cost for: ${a.name}`;}
 async function recordAssetSale(id){const a=state.assets.find(x=>String(x.id)===String(id));if(!a)return;const value=prompt(`Sale proceeds for ${a.name} (ZMW):`);if(value===null)return;if(!Number.isFinite(Number(value))||Number(value)<0){toast("Enter a valid sale amount.");return;}if(!confirm(`Record sale of ${a.name} for ${money(Number(value))}? The asset will be removed from the register and cash proceeds retained in the transaction ledger. Sale proceeds will not be counted as earned income.`))return;try{const {error}=await state.client.from("transactions").insert({household_id:state.household.id,type:"income",amount:Number(value),transaction_date:today(),category:"Asset sale proceeds",description:`Sale of asset: ${a.name}`,account_name:"Cash",payment_method:"Cash",paid_by:a.owner||"joint",source_name:"Asset sale",notes:`Asset sale; original asset value ${money(a.estimated_value)}. This proceeds is recorded separately from asset value changes.`,created_by:state.user.id});if(error)throw error;const del=await state.client.from("household_assets").delete().eq("id",id);if(del.error)throw del.error;await refresh();toast("Asset sale recorded.");}catch(e){toast("Could not record sale: "+errText(e));}}
 function exportAssetsCsv(){const rows=[["Name","Category","Purchase cost ZMW","Current value ZMW","Acquired date","Valuation date","Owner","Owner share %","Location","Linked debt ZMW","Insurance provider","Expiry date","Document URL","Monthly rental income ZMW","Depreciation/appreciation notes","Notes"],...state.assets.map(a=>[a.name,a.category,a.purchase_cost,a.estimated_value,a.acquired_on,a.valuation_date,a.owner,a.owner_share,a.location,a.linked_debt,a.insurance_provider,a.insurance_expiry,a.document_url,a.monthly_rental_income,a.depreciation_notes,a.notes])];const csv=rows.map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\r\n");downloadBlob("nkausu-house-assets.csv",new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));}

