  function renderHousehold(){const h=state.household;$("openingBalancesList").innerHTML=state.openingBalances.length?`<div class="table-wrap"><table><thead><tr><th>ACCOUNT</th><th>OPENING BALANCE</th><th></th></tr></thead><tbody>${state.openingBalances.map(a=>`<tr><td>${escapeHtml(a.account_name)}</td><td>${money(a.opening_balance)}</td><td><button class="delete-btn" data-edit-opening="${escapeHtml(a.account_name)}">Edit</button></td></tr>`).join("")}</tbody></table></div>`:"<div class='empty'>No opening balances set. Accounts currently start at K0.00.</div>";$("householdDetails").innerHTML=h?`<span>Household</span><strong>${escapeHtml(h.name)} · ${escapeHtml(h.role)}</strong>`:'<span>No household joined yet. Use an invitation code below.</span>';$("generateInvite").disabled=!(h&&h.role==="owner");}
  function setAuthMode(mode){state.authMode=mode;document.querySelectorAll("[data-auth-tab]").forEach(b=>b.classList.toggle("active",b.dataset.authTab===mode));$("signupFields").classList.toggle("hidden",mode!=="signup");$("authSubmit").textContent=mode==="signup"?"Create account":"Sign in";$("authPassword").autocomplete=mode==="signup"?"new-password":"current-password";setMessage("authMessage","");}
  function populateCategories(type,selected){const select=$("recordCategory");select.innerHTML=categories[type].map(c=>`<option ${c===selected?"selected":""}>${escapeHtml(c)}</option>`).join("");}
  function openDialog(type="income",id=null){if(!state.household){toast("This account is not linked to a household. Household membership must be configured first.");return;}state.editingId=id;const t=id?state.transactions.find(x=>String(x.id)===String(id)):null;$("transactionForm").reset();$("recordType").value=t?.type||type;$("recordAmount").value=t?.amount??"";$("recordDate").value=t?.transaction_date||today();populateCategories(t?.type||type,t?.category);$("recordDescription").value=t?.description||"";$("recordPayment").value=t?.payment_method||"Cash";$("recordAccount").value=t?.account_name||"Cash";$("recordToAccount").value=t?.to_account||"Bank";$("recordPaidBy").value=t?.paid_by||"me";$("recordNotes").value=t?.notes||"";if($("recordTags"))$("recordTags").value=Array.isArray(t?.transaction_tags)?t.transaction_tags.join(", "):"";if($("recordSource"))$("recordSource").value=t?.source_name||"";if($("recordLoan"))$("recordLoan").checked=!!t?.is_loan;if($("recordExpenseRecipient"))$("recordExpenseRecipient").value=t?.expense_recipient||"";if($("recordExpenseOwner"))$("recordExpenseOwner").value=t?.expense_owner||t?.paid_by||"me";if($("recordExpenseRefund"))$("recordExpenseRefund").checked=!!t?.expense_is_refund;if($("recordDebtPrincipal"))$("recordDebtPrincipal").checked=!!t?.is_debt_principal;if($("recordDebtId")){const oldDebt=$("recordDebtId").value;$("recordDebtId").innerHTML='<option value="">Choose debt record</option>'+state.debts.filter(d=>d.debt_type==="owed").map(d=>`<option value="${escapeHtml(d.id)}">${escapeHtml(d.name)} · ${money(d.outstanding_amount)} left</option>`).join("");$("recordDebtId").value=t?.debt_id||oldDebt||"";}if($("recordDebtSelectWrap"))$("recordDebtSelectWrap").classList.toggle("hidden",!(t?.is_debt_principal));if($("expenseDetailFields"))$("expenseDetailFields").classList.toggle("hidden",(t?.type||type)!=="expense");$("dialogTitle").textContent=t?"EDIT TRANSACTION":"ADD TRANSACTION";$("saveRecord").textContent=t?"Save changes":"Save transaction";$("transferFields").classList.toggle("hidden",(t?.type||type)!=="transfer");if($("recordLoanWrap"))$("recordLoanWrap").classList.toggle("hidden",(t?.type||type)!=="income");if($("recordSource"))$("recordSource").closest("label")?.classList.toggle("hidden",(t?.type||type)!=="income");setMessage("formMessage","");$("transactionDialog").showModal();}
  async function handleAuth(e){e.preventDefault();if(!isConfigured()){setMessage("authMessage","Configure your Supabase URL and publishable key in app.js.","error");return;}const email=$("authEmail").value.trim(),password=$("authPassword").value;$("authSubmit").disabled=true;try{if(state.authMode==="signup"){const {data,error}=await state.client.auth.signUp({email,password,options:{data:{full_name:$("displayName").value.trim()}}});if(error)throw error;if(!data.session)setMessage("authMessage","Account created. Check your email to confirm your address, then sign in.","success");else{state.user=data.user;await enterApp();}}else{const {data,error}=await state.client.auth.signInWithPassword({email,password});if(error)throw error;state.user=data.user;await enterApp();}}catch(e){setMessage("authMessage",errText(e),"error");}finally{$("authSubmit").disabled=false;}}
  async function enterApp(){showApp();await refresh();navigate(state.page||"dashboard");}
  function queueKey(){return `nkausu-offline-${state.user?.id||"anonymous"}`;}
  function getQueue(){try{return JSON.parse(localStorage.getItem(queueKey())||"[]");}catch{return [];}}
  function setQueue(q){localStorage.setItem(queueKey(),JSON.stringify(q));}
  async function syncOfflineQueue(){if(!navigator.onLine||!state.user||!state.household)return 0;const queue=getQueue();if(!queue.length)return 0;const keep=[];for(const item of queue){try{const {error}=await state.client.from("transactions").insert({...item,household_id:state.household.id,created_by:state.user.id});if(error)throw error;}catch{keep.push(item);}}setQueue(keep);const synced=queue.length-keep.length;if(synced)toast(`${synced} offline transaction(s) synced.`);return synced;}
  async function adjustDebtPrincipal(oldT,newT){const oldValid=!!(oldT&&oldT.type==="expense"&&oldT.is_debt_principal&&oldT.debt_id),newValid=!!(newT&&newT.type==="expense"&&newT.is_debt_principal&&newT.debt_id);if(oldValid){const d=state.debts.find(x=>x.id===oldT.debt_id);if(d){const {error}=await state.client.from("household_debts").update({outstanding_amount:Number(d.outstanding_amount)+Number(oldT.amount)}).eq("id",d.id);if(error)throw error;}}if(newValid){const d=state.debts.find(x=>x.id===newT.debt_id);if(!d)throw new Error("Selected debt record could not be found.");const restored=oldValid&&oldT.debt_id===newT.debt_id?Number(d.outstanding_amount)+Number(oldT.amount):Number(d.outstanding_amount);const next=Math.max(0,restored-Number(newT.amount));const {error}=await state.client.from("household_debts").update({outstanding_amount:next}).eq("id",d.id);if(error)throw error;}}
  async function saveTransaction(e){e.preventDefault();if(!state.household)return;const type=$("recordType").value,amount=Number($("recordAmount").value),oldTransaction=state.editingId?state.transactions.find(x=>String(x.id)===String(state.editingId)):null;if(!Number.isFinite(amount)||amount<=0){setMessage("formMessage","Enter an amount greater than zero.","error");return;}if(type==="expense"&&$("recordDebtPrincipal")?.checked&&$("recordExpenseRefund")?.checked){setMessage("formMessage","A payment cannot be both a refund and a loan-principal repayment.","error");return;}if(type==="expense"&&$("recordDebtPrincipal")?.checked&&!$("recordDebtId")?.value){setMessage("formMessage","Choose the loan record this principal payment reduces.","error");return;}if(type==="expense"&&$("recordDebtPrincipal")?.checked){const debt=state.debts.find(d=>d.id===$("recordDebtId").value);const available=Number(debt?.outstanding_amount||0)+(oldTransaction?.is_debt_principal&&oldTransaction.debt_id===debt?.id?Number(oldTransaction.amount||0):0);if(!debt||amount>available+0.005){setMessage("formMessage",`Principal payment cannot exceed the remaining loan balance (${money(available)}).`,"error");return;}}if(type==="transfer"&&$("recordAccount").value===$("recordToAccount").value){setMessage("formMessage","Choose two different accounts for a transfer.","error");return;}if(!state.editingId){const duplicate=state.transactions.find(t=>t.type===type&&t.transaction_date===$("recordDate").value&&Math.abs(Number(t.amount)-amount)<0.005&&(t.account_name||"Cash")===$("recordAccount").value&&t.description.trim().toLowerCase()===$("recordDescription").value.trim().toLowerCase());if(duplicate&&!confirm(`A similar ${type} with the same date, amount, account and description already exists. Save another anyway?`))return;}const payload={household_id:state.household.id,type,amount,transaction_date:$("recordDate").value,category:$("recordCategory").value,description:$("recordDescription").value.trim(),notes:$("recordNotes").value.trim()||null,transaction_tags:[...new Set(($("recordTags")?.value||"").split(",").map(x=>x.trim()).filter(Boolean))],payment_method:$("recordPayment").value,account_name:$("recordAccount").value,to_account:type==="transfer"?$("recordToAccount").value:null,paid_by:$("recordPaidBy").value,source_name:$("recordSource")?.value.trim()||null,is_loan:type==="income"&&!!$("recordLoan")?.checked,expense_recipient:type==="expense"?$("recordExpenseRecipient")?.value.trim()||null:null,expense_owner:type==="expense"?$("recordExpenseOwner")?.value||$("recordPaidBy").value:"me",expense_is_refund:type==="expense"&&!!$("recordExpenseRefund")?.checked,is_debt_principal:type==="expense"&&!!$("recordDebtPrincipal")?.checked,expense_kind:type==="expense"?( $("recordDebtPrincipal")?.checked?"debt_principal":$("recordExpenseRefund")?.checked?"refund":"ordinary"):"ordinary",debt_id:type==="expense"&&$("recordDebtPrincipal")?.checked?$("recordDebtId")?.value||null:null,attachment_path:oldTransaction?.attachment_path||null,created_by:state.user.id};const splitEnabled=type==="expense"&&!!$("recordSplitExpense")?.checked;if(splitEnabled){if(state.editingId){setMessage("formMessage","Split entries can only be created as new transactions. Cancel and add a new expense to split it.","error");return;}const rows=[...($("splitExpenseRows")?.querySelectorAll(".split-line")||[])];if(rows.length<2){setMessage("formMessage","Add at least two split lines.","error");return;}const parts=rows.map(r=>({category:r.querySelector("select").value,amount:Number(r.querySelector("input").value)}));const total=parts.reduce((n,p)=>n+p.amount,0);if(parts.some(p=>!p.category||!Number.isFinite(p.amount)||p.amount<=0)||Math.abs(total-amount)>0.005){setMessage("formMessage",`Split amounts must be positive and add up to ${money(amount)}. Current split total: ${money(total)}.`,"error");return;}payload._splitParts=parts;}const attachment=$("recordExpenseAttachment")?.files?.[0];if(attachment&&attachment.size>10*1024*1024){setMessage("formMessage","Receipt attachment must be 10 MB or smaller.","error");return;}if(attachment&&type==="expense"){try{const safe=attachment.name.replace(/[^a-zA-Z0-9._-]/g,"_");payload.attachment_path=`${state.household.id}/${crypto.randomUUID()}-${safe}`;const {error}=await state.client.storage.from("expense-attachments").upload(payload.attachment_path,attachment,{upsert:false,contentType:attachment.type||"application/octet-stream"});if(error)throw error;}catch(err){setMessage("formMessage","Could not upload receipt: "+errText(err),"error");return;}}$("saveRecord").disabled=true;try{if(state.editingId){const {error}=await state.client.from("transactions").update(payload).eq("id",state.editingId);if(error)throw error;await adjustDebtPrincipal(oldTransaction,payload);toast("Transaction updated.");}else if(!navigator.onLine){const queue=getQueue();queue.push({...payload,household_id:undefined,created_by:undefined});setQueue(queue);toast("Saved on this device; it will sync when online.");}else{if(payload._splitParts){const parts=payload._splitParts;delete payload._splitParts;const rows=parts.map((part,i)=>({...payload,amount:part.amount,category:part.category,description:`${payload.description} — ${part.category}`,notes:[payload.notes,`Split expense part ${i+1} of ${parts.length}; original total ${amount.toFixed(2)} ZMW`].filter(Boolean).join(" · ")}));const {error}=await state.client.from("transactions").insert(rows);if(error)throw error;toast(`Split expense saved as ${parts.length} category entries.`);}else{const {error}=await state.client.from("transactions").insert(payload);if(error)throw error;}await adjustDebtPrincipal(null,payload);if(type==="income"&&payload.is_loan){const debt=await state.client.from("household_debts").insert({household_id:state.household.id,name:`Loan received — ${payload.source_name||payload.description}`,debt_type:"owed",original_amount:amount,outstanding_amount:amount,due_date:null,monthly_payment:0,created_by:state.user.id});if(debt.error)toast("Transaction saved, but loan liability could not be added: "+debt.error.message);}toast("Transaction saved.");}$("transactionDialog").close();await refresh();}catch(e){setMessage("formMessage",errText(e),"error");}finally{$("saveRecord").disabled=false;}}
  async function reverseTransaction(id){const t=state.transactions.find(x=>String(x.id)===String(id));if(!t||t.is_reversed||t.is_reversal)return;if(t.is_loan||t.is_debt_principal){toast("For loan receipts or loan-principal payments, edit or delete the record and reconcile the linked liability first.");return;}if(!confirm(`Reverse “${t.description}” for ${money(t.amount)}? The original will remain in the audit trail and a compensating entry will be added.`))return;try{let payload={...t,id:undefined,created_at:undefined,updated_at:undefined,created_by:state.user.id,is_reversal:true,is_reversed:false,reversal_of:t.id,description:`REVERSAL — ${t.description}`.slice(0,180),notes:[t.notes,`Reversal of transaction ${t.id}`].filter(Boolean).join(" · ")};if(t.type==="transfer"){payload.account_name=t.to_account||"Cash";payload.to_account=t.account_name||"Cash";}else{payload.type=t.type==="income"?"expense":(t.expense_is_refund?"expense":"income");payload.category="Reversal";payload.is_loan=false;payload.expense_is_refund=false;payload.expense_kind="ordinary";payload.is_debt_principal=false;payload.debt_id=null;}const ins=await state.client.from("transactions").insert(payload);if(ins.error)throw ins.error;const upd=await state.client.from("transactions").update({is_reversed:true}).eq("id",t.id);if(upd.error){await state.client.from("transactions").delete().eq("reversal_of",t.id).eq("is_reversal",true);throw upd.error;}t.is_reversed=true;if(t.income_plan_id){const plan=state.incomePlans.find(p=>p.id===t.income_plan_id);if(plan){const adj=await state.client.from("income_plans").update({received_amount:Math.max(0,Number(plan.received_amount||0)-Number(t.amount||0)),updated_at:new Date().toISOString()}).eq("id",plan.id);if(adj.error)toast("Transaction reversed; update the linked expected-income total manually: "+adj.error.message);}}if(t.expense_plan_id){const plan=state.expensePlans.find(p=>p.id===t.expense_plan_id);if(plan){const adj=await state.client.from("expense_plans").update({paid_amount:Math.max(0,Number(plan.paid_amount||0)-Number(t.amount||0)),updated_at:new Date().toISOString()}).eq("id",plan.id);if(adj.error)toast("Transaction reversed; update the linked bill payment total manually: "+adj.error.message);}}await refresh();toast("Transaction reversed. Both entries remain visible for audit; their net account effect is zero.");}catch(e){toast("Could not reverse transaction: "+errText(e));}}
  async function deleteTransaction(id){if(!window.confirm("Delete this transaction permanently? The change will be recorded in the audit history."))return;try{const old=state.transactions.find(t=>String(t.id)===String(id));if(old?.is_debt_principal&&old.debt_id){const debt=state.debts.find(d=>d.id===old.debt_id);if(debt){const restore=await state.client.from("household_debts").update({outstanding_amount:Number(debt.outstanding_amount)+Number(old.amount)}).eq("id",debt.id);if(restore.error)throw restore.error;}}const {error}=await state.client.from("transactions").delete().eq("id",id);if(error)throw error;await refresh();toast("Transaction deleted.");}catch(e){toast("Could not delete transaction: "+errText(e));}}
