  async function saveBudget(e){e.preventDefault();if(!state.household)return;const month=$("budgetMonth").value||monthNow();try{const payload={household_id:state.household.id,created_by:state.user.id,category:$("budgetCategory").value.trim(),limit_amount:Number($("budgetLimit").value),month_start:month+"-01",owner_scope:$("budgetOwner").value,spending_kind:$("budgetKind").value,rollover_unused:$("budgetRollover").checked,notes:$("budgetNotes").value.trim()||null};const {error}=await state.client.from("household_budgets").upsert(payload,{onConflict:"household_id,category,month_start,owner_scope"});if(error)throw error;toast("Budget saved.");await refresh();$("budgetForm").reset();$("budgetMonth").value=$("budgetViewMonth").value||monthNow();}catch(e){toast("Could not save budget: "+errText(e));}}
