  async function saveAsset(e){
    e.preventDefault();
    if(!state.household){toast("Join your household first.");return;}
    const id=$("assetId").value;
    const value=Number($("assetValue").value);
    const payload={household_id:state.household.id,name:$("assetName").value.trim(),category:$("assetCategory").value,purchase_cost:Number($("assetCost").value||0),estimated_value:value,valuation_date:$("assetValuationDate").value||today(),acquired_on:$("assetDate").value||null,owner:$("assetOwner").value,owner_share:Number($("assetShare").value||100),location:$("assetLocation").value.trim()||null,linked_debt:Number($("assetDebt").value||0),insurance_provider:$("assetInsurance").value.trim()||null,insurance_expiry:$("assetExpiry").value||null,document_url:$("assetDocument").value.trim()||null,monthly_rental_income:Number($("assetRental").value||0),depreciation_notes:$("assetDepreciation").value.trim()||null,notes:$("assetNotes").value.trim()||null,created_by:state.user.id};
    try{
      let assetId=id;
      if(id){const {error}=await state.client.from("household_assets").update(payload).eq("id",id);if(error)throw error;}
      else{const {data,error}=await state.client.from("household_assets").insert(payload).select("id").single();if(error)throw error;assetId=data.id;}
      const existingHistory=(state.assetValuations||[]).filter(v=>String(v.asset_id)===String(assetId));
      const latest=existingHistory[0];
      if(!latest||Number(latest.value)!==value||String(latest.valuation_date)!==String(payload.valuation_date)){
        const {error}=await state.client.from("household_asset_valuations").insert({household_id:state.household.id,asset_id:assetId,value,valuation_date:payload.valuation_date,notes:payload.depreciation_notes,created_by:state.user.id});
        if(error)throw error;
      }
      await refresh();resetAssetForm();toast(id?"Asset updated and valuation history saved.":"Asset added and valuation history started.");
    }catch(err){toast("Could not save asset. Make sure the ASSET REGISTER UPGRADE SQL has been run: "+errText(err));}
  }
