  function downloadBlob(filename,blob){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportCsv(){const rows=[["Date","Type","Amount ZMW","Category","Source","Description","Account","To account","Payment method","Recorded by","Expense owner","Recipient","Loan received","Refund","Debt principal","Reversed","Reversal entry","Tags","Receipt path","Notes"],...state.transactions.map(t=>[t.transaction_date,t.type,t.amount,t.category,t.source_name||"",t.description,t.account_name||"Cash",t.to_account||"",t.payment_method||"Other",t.paid_by||"",t.expense_owner||"",t.expense_recipient||"",t.is_loan?"Yes":"No",t.expense_is_refund?"Yes":"No",t.is_debt_principal?"Yes":"No",t.is_reversed?"Yes":"No",t.is_reversal?"Yes":"No",(t.transaction_tags||[]).join("; "),t.attachment_path||"",t.notes||""])];const csv=rows.map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\r\n");downloadBlob("nkausu-house-transactions.csv",new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));}
  function exportBackup(){const data={format:"THE_NKAUSU_HOUSE_BACKUP",version:2,exported_at:new Date().toISOString(),household_name:state.household?.name,transactions:state.transactions,incomePlans:state.incomePlans,incomeTargets:state.incomeTargets,expensePlans:state.expensePlans,budgets:state.budgets,budgetSettings:state.budgetSettings,goals:state.goals,debts:state.debts,assets:state.assets};downloadBlob(`nkausu-house-backup-${today()}.json`,new Blob([JSON.stringify(data,null,2)],{type:"application/json"}));}
  async function restoreBackup(file){try{const data=JSON.parse(await file.text());if(data.format!=="THE_NKAUSU_HOUSE_BACKUP")throw new Error("This file is not a THE NKAUSU HOUSE backup.");if(!state.household)throw new Error("Join your household before restoring.");if(!confirm("Restore these records into your current household? Existing records will NOT be deleted. Duplicate IDs may be skipped or updated."))return;const mapping=[["transactions",data.transactions||[]],["income_plans",data.incomePlans||[]],["income_targets",data.incomeTargets||[]],["expense_plans",data.expensePlans||[]],["household_budgets",data.budgets||[]],["household_budget_settings",data.budgetSettings||[]],["savings_goals",data.goals||[]],["household_debts",data.debts||[]],["household_assets",data.assets||[]]];let count=0;for(const [table,items] of mapping){for(const item of items){const copy={...item,household_id:state.household.id,created_by:state.user.id};delete copy.created_at;delete copy.updated_at;const {error}=await state.client.from(table).upsert(copy,{onConflict:"id"});if(error)throw new Error(`${table}: ${error.message}`);count++;}}await refresh();toast(`Backup restored: ${count} records processed.`);}catch(e){toast("Restore failed: "+errText(e));}finally{$("restoreBackup").value="";}}
  function install(){if(state.installPrompt){state.installPrompt.prompt();state.installPrompt.userChoice.finally(()=>{state.installPrompt=null;$("installApp").classList.add("hidden");});}else toast("In Chrome, open the browser menu and choose Install app or Add to Home screen.");}
  function refreshSplitTotal(){const rows=[...($("splitExpenseRows")?.querySelectorAll(".split-line")||[])];const total=rows.reduce((n,r)=>n+Number(r.querySelector("input")?.value||0),0);if($("splitExpenseTotal"))$("splitExpenseTotal").textContent=`Split total: ${money(total)} · Main amount: ${money(Number($("recordAmount")?.value||0))}`;}
  function addSplitLine(category="Groceries",amount=""){const wrap=$("splitExpenseRows");if(!wrap)return;const row=document.createElement("div");row.className="split-line";row.innerHTML=`<select aria-label="Split category">${["Rent","Groceries","Electricity","Water","Transport","School expenses","Medical expenses","Maintenance","Communication","Subscriptions","Insurance","Business expenses","Other expense"].map(c=>`<option${c===category?" selected":""}>${c}</option>`).join("")}</select><input type="number" min="0.01" step="0.01" placeholder="Amount" aria-label="Split amount" value="${escapeHtml(amount)}" required><button type="button" class="delete-btn" aria-label="Remove split line">×</button>`;row.querySelector("input").addEventListener("input",refreshSplitTotal);row.querySelector("select").addEventListener("change",refreshSplitTotal);row.querySelector("button").addEventListener("click",()=>{row.remove();refreshSplitTotal();});wrap.appendChild(row);refreshSplitTotal();}
